/* Start [MWIPFACCMF ITEM_NAME : CMF_LABEL] */
BEGIN
   FOR REC IN (
       SELECT DISTINCT FACTORY FROM MWIPFACDEF
       MINUS
       SELECT DISTINCT FACTORY FROM MWIPFACCMF
       WHERE ITEM_NAME = 'CMF_LABEL'
       )
   LOOP
     values (REC.FACTORY,'CMF_LABEL','FEED_POSITION','CUT_POSITION','BACK_F_LENGTH','PRINT_MODE','TAG_MODE_FLAG','CUT_INTERVAL','SENSOR_TYPE','ISSUE_MODE','TAG_ROTATION','RIBON_OPTION',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ','N','N','N','A','A','N','A','A','A','A',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ','N','N','N','N','N','N','N','N','N','N',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ','PRINTER_MODE','YESNO',' ','SENSOR_TYPE','ISSUE_MODE','TAG_ROTATION','RIBON_OPTION',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ','ADMIN','20160429154737','ADMIN','20160504102237');
   END LOOP;
END;
/
/* End [MWIPFACCMF ITEM_NAME : CMF_LABEL] */

